+/// A rotation about world X by `deg`: the axis leans in Y, its X stays.
+fn lean_y(deg: f64) -> impl Fn(Point3) -> Point3 {
+    let (s, c) = deg.to_radians().sin_cos();
+    move |p| Point3::new(p.x, p.y * c - p.z * s, p.y * s + p.z * c)
